INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT146-S3-Q19$batch13$, 146, 3, 19, $batch13$Role$batch13$, $batch13$Jurist: To ensure that a legal system remains just, it is important to guarantee that lawbreaking does not give lawbreakers an unfair advantage over law abiders. Thus, notwithstanding any other goals that criminal punishment may serve, it should certainly attempt to ensure that criminal wrongdoing remains profitless.$batch13$, $batch13$The jurist’s claim that it is important to guarantee that lawbreaking does not give lawbreakers an unfair advantage over law abiders functions in the argument in which one of the following ways?$batch13$, $batch13$B$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=146 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT146-S3-Q19$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$It states a condition that, if fulfilled, will ensure that a legal system remains just.$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT146-S3-Q19$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$It expresses a principle that is offered as support for the conclusion.$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT146-S3-Q19$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$It is a conclusion for which the only support offered is the claim that the legal system serves multiple goals.$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT146-S3-Q19$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$It is a premise presented as support for the claim that the most important goal of criminal punishment is to ensure that criminal wrongdoing remains profitless.$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT146-S3-Q19$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$It is presented as refuting an argument that criminal punishment has goals other than guaranteeing that lawbreaking remains profitless.$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT146-S3-Q19$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT146-S3-Q19$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Evidence$batch13$, $batch13$To keep a legal system just, it is important to guarantee that lawbreaking gives lawbreakers no unfair advantage over law abiders.$batch13$), (1, $batch13$Conclusion$batch13$, $batch13$Whatever other goals criminal punishment serves, it should try to keep criminal wrongdoing profitless.$batch13$), (2, $batch13$Evaluate$batch13$, $batch13$"Thus" marks the second sentence as the conclusion, so the first sentence is support. It's a general principle about justice. The conclusion applies it to punishment: if crime pays, lawbreakers gain an unfair advantage.$batch13$), (3, $batch13$Goal$batch13$, $batch13$A principle offered in support of the conclusion.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT146-S3-Q19$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$The principle says the guarantee is important to justice, not that meeting it ensures justice.$batch13$), ($batch13$B$batch13$, $batch13$A general principle, followed by "Thus" and the conclusion it supports.$batch13$), ($batch13$C$batch13$, $batch13$It's a premise. Nothing in the passage supports it.$batch13$), ($batch13$D$batch13$, $batch13$The conclusion doesn't call profitlessness the most important goal. "Notwithstanding any other goals" leaves the ranking open.$batch13$), ($batch13$E$batch13$, $batch13$The jurist grants that punishment may have other goals. Nothing is refuted.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT146-S3-Q19$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
